language sql stable security definer set search_path = pg_catalog, ff_private
as $$ select exists(select 1 from public.league_members m where m.league_id=p_league and m.user_id=auth.uid() and m.status='active' and m.role='leader') $$;
create function ff_private.is_organizer(p_league uuid) returns boolean
language sql stable security definer set search_path = pg_catalog, ff_private
as $$ select exists(select 1 from public.match_organizers o join public.league_members m on m.league_id=o.league_id and m.user_id=o.user_id where o.league_id=p_league and o.user_id=auth.uid() and m.status='active') $$;
