language sql stable security definer set search_path = pg_catalog, ff_private
as $$ select exists(select 1 from public.fantasy_teams t join public.league_members m on m.league_id=t.league_id and m.user_id=t.manager_id where t.league_id=p_league and t.id=p_team and t.manager_id=auth.uid() and m.status='active') $$;
