  foreach tbl in array array['profiles','leagues','league_members','match_organizers','player_profiles','real_football_teams','real_team_players','league_players','player_suggestions','player_approval_logs','seasons','gameweeks','fantasy_teams','fantasy_squad_players','fantasy_lineups','fantasy_lineup_players','transfers','real_matches','match_revisions','real_match_lineups','real_match_lineup_players','temporary_participant_authorizations','match_events','match_submissions','match_approvals','scoring_rule_sets','scoring_rule_values','official_match_results','match_player_performances','scoring_runs','fantasy_score_items','fantasy_scores','head_to_head_fixtures','league_standings','notifications','audit_logs'] loop
    execute format('alter table public.%I enable row level security',tbl);
