end $$;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid());
create policy member_league on public.leagues for select to authenticated using(ff_private.is_member(id));
create policy members_own_or_leader on public.league_members for select to authenticated using(ff_private.is_member(league_id) and (user_id=auth.uid() or ff_private.is_leader(league_id)));
create policy organizers_member_read on public.match_organizers for select to authenticated using(ff_private.is_member(league_id));
-- League-scoped public-in-league data; no cross-tenant rows.
do $$ declare tbl text; begin
  foreach tbl in array array['player_profiles','real_football_teams','real_team_players','league_players','seasons','gameweeks','fantasy_teams','scoring_rule_sets','scoring_rule_values','official_match_results','match_player_performances','scoring_runs','fantasy_scores','head_to_head_fixtures','league_standings'] loop
    execute format('create policy league_read on public.%I for select to authenticated using (ff_private.is_member(league_id))',tbl);
  end loop;
end $$;
